def solve_demo(grid):
    # Find 3-square centers (from vertical 3s)
    top_center, bottom_center = None, None

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == 3:
                # Count 3s around (r,c) - if >= 3 in a small region, it's part of a square
                count = 0
                positions = []
                for dr in range(max(0, r-2), min(len(grid), r+2)):
                    for dc in range(max(0, c-2), min(len(grid[0]), c+2)):
                        if grid[dr][dc] == 3:
                            count += 1
                            positions.append((dr, dc))
                if count >= 3:
                    # This is part of a square
                    avg_r = sum(p[0] for p in positions) / count
                    avg_c = sum(p[1] for p in positions) / count
                    if top_center is None:
                        top_center = (avg_r, avg_c)
                    else:
                        bottom_center = (avg_r, avg_c)

    if top_center is None:
        return [[0] * len(grid[0]) for _ in range(len(grid))]

    top_center, bottom_center = top_center, bottom_center
    r_diff = abs(bottom_center[0] - top_center[0])
    c_diff = abs(bottom_center[1] - top_center[1])
    radius = int(r_diff + c_diff)

    output = [row[:] for row in grid]
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == 0:  # Background
                dist = abs(r - top_center[0]) + abs(c - top_center[1]) + \
                       abs(r - bottom_center[0]) + abs(c - bottom_center[1])
                if dist <= radius:
                    output[r][c] = 1

    return output

