import json
from rlm import emit

# New hypothesis: For each square, determine bounding columns using nearest 2-lines
# Then fill 3 rows around the square center between those columns

def demo2_pattern_solver(grid):
    rows, cols = len(grid), len(grid[0])
    centers_list = find_square_centers(grid)
    centers = []
    seen = set()
    for c in centers_list:
        cr, cc = int(round(c[0])), int(round(c[1]))
        key = (cr, cc)
        if key not in seen:
            centers.append(key)
            seen.add(key)

    output = [row[:] for row in grid]
    two_lines = find_two_line_cols(grid)
    two_line_cols = set(t[0] for t in two_lines)

    if len(centers) == 2 and two_lines:
        # For each square, find the two 2-lines that bound it
        for (r, c) in centers:
            # Find column range: between the two 2-lines nearest to c
            # The 2-lines are vertical dividers, so we find left and right
            left_col = max(tc for tc in two_line_cols if tc < c) if any(tc < c for tc in two_line_cols) else None
            right_col = min(tc for tc in two_line_cols if tc > c) if any(tc > c for tc in two_line_cols) else None

            # If no left/right, use min/max
            if left_col is None:
                sorted_cols = sorted(two_line_cols)
                left_col = sorted_cols[0]
                if sorted_cols and c > sorted_cols[-1]:
                    left_col = sorted_cols[-1]  # If square is right of all ticks

            if right_col is None:
                sorted_cols = sorted(two_line_cols)
                if sorted_cols:
                    right_col = sorted_cols[-1]

            # Now fill rows r-1, r, r+1 from left_col+1 to right_col-1
            for rr in [r-1, r, r+1]:
                if 0 <= rr < rows:
                    for cc in range(left_col, right_col + 1):
                        if cc in two_line_cols:
                            continue
                        if output[rr][cc] == 3 or output[rr][cc] == 2:
                            continue
                        output[rr][cc] = 1

    return output

